{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Risperidone has a direct absolute oral bioavailability of 70% in humans, providing strong high-F evidence with very high transferability to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Bitopertin shows high absolute bioavailability in healthy volunteers, supported by minimal CYP3A4 inhibition effects on exposure, and is highly transferable to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Brexpiprazole has a direct absolute oral bioavailability of 95% in healthy subjects, a strong high-F anchor with high transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Daridorexant has a direct absolute oral bioavailability of 62% in humans, supporting high F with high transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Nilotinib, a structurally related kinase inhibitor, has a direct absolute oral bioavailability of 31% under fasted conditions in humans, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Predicted nilotinib absolute oral bioavailability was reported as low (<25%) in healthy humans, but this is a model-based prediction outweighed by direct human absolute measurements and by the query's more solubilizing pyrrolidine/sulfonamide features.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct absolute human bioavailability data from highly transferable analogues consistently support F >=20%: risperidone 70%, brexpiprazole 95%, daridorexant 62%, and even nilotinib 31%. The only sub-20% values are predicted nilotinib simulations, which are outweighed by direct measurements and by the query's solubilizing basic pyrrolidine and sulfonamide groups.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the exact query molecule.",
    "Nilotinib simulations predict F <25% under some conditions, introducing some uncertainty about solubility-limited absorption; however direct human absolute F is 31%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

